def extract_shapes(g):
    """Each nonzero color's cells as a normalized (top-left anchored) mini-grid, sorted left-to-right."""
    cl={}
    for i,row in enumerate(g):
        for j,v in enumerate(row):
            if v: cl.setdefault(v,[]).append((i,j))
    out=[]
    for c,pts in cl.items():
        rs=[p[0] for p in pts]; cs=[p[1] for p in pts]
        r0,c0=min(rs),min(cs)
        h=max(rs)-r0+1; w=max(cs)-c0+1
        m=[[0]*w for _ in range(h)]
        for r,x in pts:
            m[r-r0][x-c0]=c
        out.append((c0,m))
    out.sort(key=lambda t:t[0])
    return [m for _,m in out]

def transform(g):
    """Flip each shape vertically, pack along the diagonal, each starting at prev's top-left + (h-1, w-1); later shapes overwrite."""
    grid=[[0]*len(g[0]) for _ in g]
    tr=tc=0
    for m in extract_shapes(g):
        m=m[::-1]
        h,w=len(m),len(m[0])
        for i in range(h):
            for j in range(w):
                if m[i][j] and tr+i<len(grid) and tc+j<len(grid[0]):
                    grid[tr+i][tc+j]=m[i][j]
        tr+=h-1; tc+=w-1
    return grid

