lib = '''"""Shared helpers for ARC shape tasks."""

import json
import os


def extract_shapes(grid):
    """Extract nonzero-color connected shapes from a grid as (color, cells, top-left, bbox) sorted by leftmost column."""
    h, w = len(grid), len(grid[0])
    cells = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c]:
                cells.setdefault(grid[r][c], []).append((r, c))
    shapes = []
    for color, cl in cells.items():
        top, left = min(r for r, c in cl), min(c for r, c in cl)
        shapes.append({"color": color, "cells": cl, "top_left": (top, left),
                       "h": max(r for r, c in cl) - top + 1, "w": max(c for r, c in cl) - left + 1})
    shapes.sort(key=lambda s: s["top_left"][1])
    return shapes


def vflip(cells, h, w):
    """Vertically flip normalized cells within an h x w bounding box."""
    return sorted((h - 1 - r, c) for r, c in cells)


def pack_diagonal(shapes, size):
    """Chain flipped shapes along the diagonal: next top-left = prev bbox corner, later shapes overwrite."""
    g = [[0] * size for _ in range(size)]
    tr = tc = 0
    for s in shapes:
        cl = vflip([(r - s["top_left"][0], c - s["top_left"][1]) for r, c in s["cells"]], s["h"], s["w"])
        for r, c in cl:
            g[tr + r][tc + c] = s["color"]
        tr, tc = tr + s["h"] - 1, tc + s["w"] - 1
    return g


def run_pairs(task_name, transform, progs_dir=None):
    """Run a task transform on all kept pairs in its .json and report pass/fail per pair."""
    progs_dir = progs_dir or os.path.dirname(os.path.abspath(__file__))
    pairs = json.load(open(os.path.join(progs_dir, task_name + ".json")))
    results = [transform(pr["input"]) == pr["output"] for pr in pairs]
    print(task_name, results)
    return all(results)
